import{_ as e,o as t,c as s,Q as a}from"./chunks/framework.b67c47e6.js";const i="/assets/upload-dialog.1d3acfa6.svg",n="/assets/general-arrangement.61efca9c.svg",o="/assets/files-table.958c803d.svg",l="/assets/status-to-split.885a30ee.svg",r="/assets/status-not-in-design.f558b276.svg",d="/assets/status-not-scanned.96c39212.svg",h="/assets/status-waiting.72842517.svg",p="/assets/status-splitting.5ddb2fb7.svg",g="/assets/status-split-failed.74e54607.svg",c="/assets/status-split.533ca22c.svg",u="/assets/status-in-design.b9e8a428.svg",f="/assets/status-scanned.bbcd6769.svg",m="/assets/update-designs-dialog.e1f49fb1.svg",q=JSON.parse('{"title":"Files and Update designs","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/projects/index.md","filePath":"tutorials/projects/index.md","lastUpdated":1793288100000}'),w={name:"tutorials/projects/index.md"},b=a('<h1 id="files-and-update-designs" tabindex="-1">Files and Update designs <a class="header-anchor" href="#files-and-update-designs" aria-label="Permalink to &quot;Files and Update designs&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#upload-files">Upload Files</a><ul><li><a href="#table-of-uploaded-files">Table of uploaded files</a></li></ul></li><li><a href="#update-designs">Update designs</a><ul><li><a href="#split-building-ifcs">Split building IFCs</a></li><li><a href="#create-and-revise-designs">Create and revise designs</a></li><li><a href="#link-details">Link details</a></li><li><a href="#analysis-prepare-the-viewer">Analysis (prepare the viewer)</a></li></ul></li></ul></nav><h2 id="upload-files" tabindex="-1">Upload Files <a class="header-anchor" href="#upload-files" aria-label="Permalink to &quot;Upload Files&quot;">​</a></h2><p>Files for each project are uploaded in <strong>Files</strong>, in the project menu under <strong>Designs</strong>:</p><p>Click <strong>Upload</strong>. In the upload dialog, pick a <strong>file group</strong> first, and optionally a <strong>tipo</strong>, then drop, paste or browse the files and click <strong>Upload</strong>. The file group tells the system what the file is, and you choose it yourself. It starts on <strong>Assembly drawings (.pdf)</strong>.</p><p>When the upload ends, the dialog shows how many files were uploaded and an <strong>Update designs</strong> button. Nothing runs on its own: you decide when the designs are updated, for example after the last of several uploads.</p><p><img src="'+i+'" alt="The upload dialog"></p><ol><li>The file group: what the files are. Pick it before you add the files.</li><li>Drop, paste or browse the files. All of them get the group you picked.</li></ol><p>The file groups are:</p><ul><li><strong>Assembly Files</strong>: Assembly IFCs (.ifc), Extra Assembly IFCs (.ifc), Assembly drawings (.pdf), Machine Files (.jjs, .wup, .btl).</li><li><strong>Module Files</strong>: Module IFCs (.ifc), Extra Module IFCs (.ifc), Module drawings (.pdf).</li><li><strong>Project Files</strong>: Project IFCs (.ifc), External IFCs (.ifc), Project drawings (.pdf).</li><li><strong>Details and documentation</strong>: Details (.pdf), Documentation (.pdf, .jpeg, .png), Specifications (.pdf, text). Documentation and specifications can also be added as text with the <strong>Add as text</strong> switch.</li></ul><p>The file name decides which design a file belongs to:</p><ul><li><p>IFCs: used for the 3D viewer, BoMs and machine files. The system reads them with the project&#39;s IFC Parsing Setup. The file name without extension is the design name. Example: &quot;PNL30-25.ifc&quot; belongs to design &quot;PNL30-25&quot;.</p></li><li><p>Extra IFCs: the design name is the part before the first &quot; - &quot;. Example: &quot;PNL30-25 - Installations.ifc&quot;.</p></li><li><p>Machine files: the file name without extension is the design name. Example: &quot;PNL30-25.btl&quot;.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Full Project IFCs</p><p>You can also upload full project IFCs and the system can split them into one IFC per design. Upload them in the <strong>Project IFCs (.ifc)</strong> group. The file name does not matter. Example: &quot;OlaraAvenue15.ifc&quot;.</p></div><ul><li><p>Drawings: .pdf file format. They are shown in the viewer. Drawing file names must follow the format &quot;Merk DESIGN_NAME - DRAWING_NUMBER - DRAWING_NAME.pdf&quot;. The word &quot;Merk&quot; at the start is optional. Example: &quot;Merk PNL30-25 - 1 - Zone 0 MAIN VIEW.pdf&quot;. If a drawing name does not follow this format, the upload shows a warning.</p></li><li><p>Details and documentation: .pdf file format. Also shown in the viewer. The file name without extension is the detail name that the system looks for in drawings. Example: &quot;V-12.pdf&quot;. Documentation files are linked to every design of the project.</p></li></ul><div class="info custom-block"><p class="custom-block-title">Full Project PDFs</p><p>In design mode, the viewer shows a &quot;General Arrangement&quot; entry at the top of the list. It opens the full project IFCs in 3D and the drawings uploaded as <strong>Project drawings (.pdf)</strong>, one button per drawing.</p><p><img src="'+n+'" alt="The viewer in design mode, on the General Arrangement"></p><ol><li>The list filter set to <strong>Design</strong>.</li><li>The <strong>General Arrangement</strong> entry.</li><li>The designs, with their revisions. Older revisions are red.</li><li><strong>3D</strong> and one button per project drawing.</li></ol></div><h3 id="table-of-uploaded-files" tabindex="-1">Table of uploaded files <a class="header-anchor" href="#table-of-uploaded-files" aria-label="Permalink to &quot;Table of uploaded files&quot;">​</a></h3><p>The table of files is shown below the upload summary. The summary counts the files, how many are linked to a design and how many name a design that does not exist, and shows the project&#39;s parsing setup with a link to change it.</p><p><img src="'+o+'" alt="The Files view"></p><ol><li><strong>Upload</strong> and <strong>Update designs</strong>. The number on Update designs counts the pending files.</li><li>The summary: files, files linked to a design, and files that name a design that does not exist.</li><li>The search and <strong>Only latest versions</strong>.</li><li>The design of each file. A full IFC shows how many designs came out of it; an orange chip names a design that does not exist.</li><li>The status of each file, explained below.</li></ol><p>Use <strong>Filename search</strong> to filter the table, and <strong>Only latest versions</strong> to hide older versions of files uploaded again with the same name. Select rows to delete, download or update designs from several files at once. The <strong>Design</strong> column shows the design each file is linked to.</p><p>Each file shows one status. The orange ones are pending: the next <strong>Update designs</strong> takes them in.</p><table><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td><img src="'+l+'" alt="To split"></td><td>A Project, External or Module IFC that has not been split yet.</td></tr><tr><td><img src="'+r+'" alt="Not in a design"></td><td>A design file (IFC, BTLx, drawing, machine file) that is not attached to its design yet.</td></tr><tr><td><img src="'+d+'" alt="Not scanned"></td><td>A drawing or detail that has not been scanned for detail names yet. A drawing only waits for this when the project has details or specs to find in it.</td></tr><tr><td><img src="'+h+'" alt="Waiting"></td><td>An update is running and works on this file. A file in this state cannot be deleted.</td></tr><tr><td><img src="'+p+'" alt="Splitting"></td><td>The file is being split. The percentage updates while the split runs.</td></tr><tr><td><img src="'+g+'" alt="Split failed"></td><td>The split failed for this file. Click the status to see the warnings.</td></tr><tr><td><img src="'+c+'" alt="Split"></td><td>This full IFC has been split.</td></tr><tr><td><img src="'+u+'" alt="In a design"></td><td>The file is attached to its design.</td></tr><tr><td><img src="'+f+'" alt="Scanned"></td><td>The file has been scanned for detail names.</td></tr></tbody></table><p>The project menu shows the same number on <strong>Files</strong> from any page of the project, so you see that files are waiting without opening this view. While an update runs, the menu shows a spinner there, and a red mark if it failed.</p><h2 id="update-designs" tabindex="-1">Update designs <a class="header-anchor" href="#update-designs" aria-label="Permalink to &quot;Update designs&quot;">​</a></h2><p><strong>Update designs</strong> brings the project&#39;s designs in line with its files. It runs three steps, in this order:</p><ol><li><a href="#split-building-ifcs">Split building IFCs</a>: Project, Module and External IFCs become one IFC per panel (and per module).</li><li><a href="#create-and-revise-designs">Create and revise designs</a>: designs are created and get the files that belong to them.</li><li><a href="#link-details">Link details</a>: drawings and IFCs are scanned for detail names.</li></ol><p>There are two ways to start it:</p><ul><li><strong>Update designs</strong> at the top of the table works on the <strong>pending files</strong>: the files with an orange status. This is the usual way after an upload.</li><li>Select files in the table and click <strong>Update designs from N files</strong> in the selection bar, or use <strong>Update designs from this file</strong> in the row menu. This works on the selected files only, even if they were already done: for example to split a file again with other levels, or to update only some designs.</li></ul><p>Both open the same dialog. It shows what will happen before anything runs.</p><p><img src="'+m+'" alt="The Update designs dialog"></p><ol><li>What the update works on: the pending files, or the selected ones.</li><li>The splitting engine, see <a href="#split-building-ifcs">Split building IFCs</a>.</li><li>What each step will do: the files to split, the designs that are created or get a new revision, and the unbuilt units that move to the new revision.</li><li>The plan in one sentence, and the button. When units move, the button says how many.</li></ol><p>Each step has a switch. It starts on when the step has pending files, and off when it has none; the step then says what it already did, for example <em>Nothing pending · 2 building IFCs already split</em>. You can always turn it on: it then takes the files it already did again. This is what you need after changing the IFC Parsing Setup, when the building IFCs must be split again. To do only some files again, select them in the table and use <strong>Update designs from N files</strong>. The settings are folded under the step, and the dialog opens with the settings of the project&#39;s last update.</p><p>While an update runs, the banner lists the three steps: a spinner on the one running, with its progress, a check on the ones done, and an empty circle on the ones waiting.</p><p>While the update runs, a banner above the table shows the step and its progress. When it ends, the banner shows how many designs are new or revised, which files could not be split, and the split warnings. The table, the designs and the counts reload on their own. Close the banner when you have read it.</p><p>Only one update runs in a project at a time. Production Counts stays open while the IFCs are split, and is locked while designs are created and revised, until the update ends: that step moves units and counts to the new revisions.</p><div class="tip custom-block"><p class="custom-block-title">The update stopped responding</p><p>An update reports its progress every minute. If it reports nothing for 30 minutes, the banner says <em>The update stopped responding</em> and offers <strong>Mark as stopped</strong>, which unlocks its files so you can start a new one. If it was still running after all, it finishes anyway.</p></div><h3 id="split-building-ifcs" tabindex="-1">Split building IFCs <a class="header-anchor" href="#split-building-ifcs" aria-label="Permalink to &quot;Split building IFCs&quot;">​</a></h3><p>Full IFCs are split into one IFC per design. The new files are added to the project as Assembly IFCs (and Module IFCs) and can be downloaded. The split also stores the quantity of each design and the phases and batches found in the IFC, so they are available in Production Counts. How assemblies are found in the IFC depends on the IFC Parsing Setup.</p><p>The split is available when the IFC splitter module is enabled for your company. The designs of the split files are created in the next step of the same update.</p><p>There are two engines:</p><ul><li><strong>Standard</strong> can split into modules, assemblies in modules, and assemblies at the project root. Pick the <strong>levels</strong> you want. By default it makes assemblies in modules and at the project root.</li><li><strong>Classic</strong> makes one IFC per assembly. It cannot split a parsing setup that finds assemblies by a part property.</li></ul><p>A project keeps the engine it was split with. A project that was never split starts on <strong>Standard</strong>. If you switch engine on a project that was already split, the dialog warns you: design names can differ between engines, and designs that change name are created again.</p><div class="tip custom-block"><p class="custom-block-title">Settings</p><p>☑️ <strong>Also split Module IFCs</strong> Also splits the files uploaded as Module IFCs. Off by default: a Module IFC is normally a design of its own.</p><p>☑️ <strong>Skip standard library names</strong> Does not create IFCs for designs that already exist in the standard library.</p></div><p>If a file cannot be split, the other files go on, and the designs of the failed file are left as they were.</p><h3 id="create-and-revise-designs" tabindex="-1">Create and revise designs <a class="header-anchor" href="#create-and-revise-designs" aria-label="Permalink to &quot;Create and revise designs&quot;">​</a></h3><p>The system collects the IFCs, drawings and machine files and creates &quot;design&quot; objects.</p><ul><li><p>A list of design names is built from the file names of assembly and module IFCs, drawings and machine files.</p></li><li><p>Each file is attached to its design. All the documentation files are linked to every design, so they are always available.</p></li><li><p>When a design gets a new file, it gets a new revision, and its units that are not built yet move to the new revision.</p></li></ul><p>Units are not created here. Create them in <a href="/guide/quantities/">Production Counts</a> with <strong>Update production</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Settings</p><p>☑️ <strong>Keep revision numbers</strong> Designs keep their revision number when they get new files.</p><p>☑️ <strong>Draw from IFC</strong> Generates drawings from the IFC of each design, with the default set of views.</p></div><h3 id="link-details" tabindex="-1">Link details <a class="header-anchor" href="#link-details" aria-label="Permalink to &quot;Link details&quot;">​</a></h3><p>Details can be automatically detected in IFCs and PDF drawings. Found detail names are linked to the design and then shown in the viewer. Only the drawings that were not scanned yet are scanned; when a new detail is uploaded, every drawing is scanned again for it. In a project with no details and no specs, drawings are not scanned and do not count as pending.</p><div class="tip custom-block"><p class="custom-block-title">Settings</p><p>☑️ <strong>Scan drawings</strong> Drawings are scanned to find detail and specification names, and details are scanned to find specification names. On by default.</p><p>☑️ <strong>Scan IFCs</strong> IFCs are scanned for detail names in the property &quot;DET_NUMBER&quot;.</p></div><p>If your detail names can&#39;t be detected by the system, you may have a rasterized export, or a rasterized font in a vectorized export, such as the <a href="https://www.autodesk.com/support/technical/article/caas/sfdcarticles/sfdcarticles/How-to-create-selectable-and-searchable-text-in-a-PDF-from-AutoCAD.html" target="_blank" rel="noreferrer">well known issue with AutoCad</a>.</p><h3 id="analysis-prepare-the-viewer" tabindex="-1">Analysis (prepare the viewer) <a class="header-anchor" href="#analysis-prepare-the-viewer" aria-label="Permalink to &quot;Analysis (prepare the viewer)&quot;">​</a></h3><p>The analysis starts automatically when a design gets a new IFC, for example after Update designs. There is no button for it in the Update designs dialog. If the company setting <strong>Launch analysis automatically</strong> is off, or you need to run it again, select the designs in <strong>Designs</strong> and click <strong>Force analysis</strong>. The <strong>Analysis</strong> column of the designs table shows the status of each design.</p><div class="warning custom-block"><p class="custom-block-title">Slow task!</p><p>⚠️ This operation takes time. It runs many heavy computations and database tasks.</p></div><ul><li><p>IFC geometry is analyzed to find the rotation and translation matrices (orientation of the panel in the world coordinate system).</p></li><li><p>Panel size and bruto/neto areas are also calculated here. So if you use bruto areas in Production Counts, you need to wait for this operation.</p></li><li><p>Each part of the IFC is analyzed, generating drawings and metadata which are saved in the database. This gives fast access to the information when the user clicks on a part in the 3D viewer.</p></li><li><p>Drawings are only generated for wood and plate parts, and for parts in custom branches marked for logistics in the IFC Parsing Setup. So, if your IFC Parsing Setup is incomplete, some part drawings may be missing.</p></li></ul>',57),y=[b];function v(I,F,k,C,T,_){return t(),s("div",null,y)}const A=e(w,[["render",v]]);export{q as __pageData,A as default};
